const { useEffect, useLayoutEffect, useRef, useState } = React;

// ---- Scroll Snap 实验台（本文各块共用）----

const ALIGN_RATIO = { start: 0, center: 0.5, end: 1 };

// 按规范的对齐规则，算出每个子项在该轴上的吸附位置（即对齐时容器的 scroll 偏移）
const snapPositions = (scroller, axis) => {
  const style = getComputedStyle(scroller);
  const vertical = axis === "y";
  const client = vertical ? scroller.clientHeight : scroller.clientWidth;
  const max = (vertical ? scroller.scrollHeight : scroller.scrollWidth) - client;
  const padStart = parseFloat(vertical ? style.scrollPaddingTop : style.scrollPaddingLeft) || 0;
  const padEnd = parseFloat(vertical ? style.scrollPaddingBottom : style.scrollPaddingRight) || 0;
  return [...scroller.querySelectorAll("[data-snap]")].map(item => {
    const itemStyle = getComputedStyle(item);
    const aligns = itemStyle.scrollSnapAlign.split(" ");
    const align = vertical ? aligns[0] : aligns[1] ?? aligns[0];
    const marginStart = parseFloat(vertical ? itemStyle.scrollMarginTop : itemStyle.scrollMarginLeft) || 0;
    const marginEnd = parseFloat(vertical ? itemStyle.scrollMarginBottom : itemStyle.scrollMarginRight) || 0;
    const start = (vertical ? item.offsetTop : item.offsetLeft) - marginStart;
    const size = (vertical ? item.offsetHeight : item.offsetWidth) + marginStart + marginEnd;
    const ratio = ALIGN_RATIO[align];
    const port = client - padStart - padEnd;
    const position = ratio === undefined ? null : start + size * ratio - padStart - port * ratio;
    return { label: item.dataset.snap, position: position === null ? null : Math.round(Math.min(max, Math.max(0, position))) };
  });
};

// 滚动偏移、吸附点与 scrollsnapchange 报告的当前吸附目标
const useSnapState = (scrollerRef, axis, deps) => {
  const [state, setState] = useState({ offset: 0, max: 0, client: 0, points: [], snapped: null });
  const readRef = useRef(() => {});
  readRef.current = () => {
    const scroller = scrollerRef.current;
    if (!scroller) return;
    const vertical = axis === "y";
    const client = vertical ? scroller.clientHeight : scroller.clientWidth;
    setState(current => ({
      ...current,
      offset: Math.round(vertical ? scroller.scrollTop : scroller.scrollLeft),
      client,
      max: (vertical ? scroller.scrollHeight : scroller.scrollWidth) - client,
      points: snapPositions(scroller, axis),
    }));
  };
  useLayoutEffect(() => readRef.current(), deps);
  useEffect(() => {
    const scroller = scrollerRef.current;
    const read = () => readRef.current();
    const snap = event => {
      const target = axis === "y" ? event.snapTargetBlock : event.snapTargetInline;
      setState(current => ({ ...current, snapped: target?.dataset?.snap ?? null }));
    };
    const observer = new ResizeObserver(read);
    observer.observe(scroller);
    scroller.addEventListener("scroll", read, { passive: true });
    scroller.addEventListener("scrollsnapchange", snap);
    return () => {
      observer.disconnect();
      scroller.removeEventListener("scroll", read);
      scroller.removeEventListener("scrollsnapchange", snap);
    };
  }, [axis]);
  return state;
};

const nearestOf = (points, offset) =>
  points.filter(point => point.position !== null).reduce((best, point) => (!best || Math.abs(point.position - offset) < Math.abs(best.position - offset) ? point : best), null);

// 滚动位置图：整条为可滚动范围，窗口为当前可视区，刻度为各吸附点
const SnapRuler = ({ state, highlight }) => {
  const total = state.max + state.client || 1;
  return (
    <div className="flex flex-col gap-1.5">
      <div className="relative h-7 rounded-tau-sm border border-line-1 bg-surface">
        <div
          className="absolute inset-y-0 rounded-tau-sm bg-accent-soft"
          style={{ left: `${(state.offset / total) * 100}%`, width: `${(state.client / total) * 100}%` }}
        />
        {state.points.map(point =>
          point.position === null ? null : (
            <span
              key={point.label}
              className={`absolute top-1 bottom-1 w-0.5 rounded-full ${point.label === highlight ? "bg-warn" : "bg-accent"}`}
              style={{ left: `${(point.position / total) * 100}%` }}
            />
          )
        )}
      </div>
      <div className="flex justify-between font-tau-mono text-tau-tiny text-ink-3">
        <span>0</span>
        <span>可视窗口 · 吸附点</span>
        <span>{state.max}px</span>
      </div>
    </div>
  );
};

const CssView = ({ lines }) => (
  <pre className="m-0 overflow-x-auto rounded-tau-md border border-line-1 bg-surface p-3 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
    {lines.map((line, index) => (
      <div key={index}>
        {line.map((part, partIndex) =>
          typeof part === "string" ? (
            <span key={partIndex}>{part}</span>
          ) : (
            <span key={partIndex} className="rounded-tau-sm bg-accent-soft px-0.5 text-accent-text">
              {part.text}
            </span>
          )
        )}
      </div>
    ))}
  </pre>
);

const Readout = ({ rows }) => (
  <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-4 gap-y-1.5 rounded-tau-md bg-hover px-3 py-2.5">
    {rows.map(([label, value]) => (
      <React.Fragment key={label}>
        <dt className="text-tau-sm text-ink-3">{label}</dt>
        <dd className="m-0 min-w-0 break-all font-tau-mono text-tau-sm text-ink-1">{value}</dd>
      </React.Fragment>
    ))}
  </dl>
);

const TONES = ["bg-tag-1", "bg-tag-2", "bg-tag-3", "bg-tag-4", "bg-tag-5"];

const CARD_VARIANTS = {
  default: "border-line-1 bg-surface",
  active: "border-accent bg-surface",
  warn: "border-warn bg-warn-soft",
};

// 吸附子项的统一外观：序号 + 色点
const SnapCard = ({ label, index, className = "", variant = "default", note, children, align = "start", style }) => (
  <div
    data-snap={label}
    className={`flex flex-col justify-between rounded-tau-sm border p-4 ${CARD_VARIANTS[variant]} ${className}`}
    style={{ scrollSnapAlign: align, ...style }}
  >
    <span className="flex items-center gap-2">
      <span className={`size-2 rounded-full ${TONES[index % TONES.length]}`} />
      <span className="text-tau-sm text-ink-3">{note}</span>
    </span>
    <span className="font-tau-mono text-tau-title text-ink-1">{label}</span>
    {children}
  </div>
);

const TYPES = ["none", "y mandatory", "y proximity"];
const SECTIONS = ["01", "02", "03", "04", "05"];

const Component = () => {
  const scrollerRef = useRef(null);
  const [type, setType] = useState("y mandatory");
  const state = useSnapState(scrollerRef, "y", [type]);
  const nearest = nearestOf(state.points, state.offset);
  const gap = nearest ? state.offset - nearest.position : 0;

  return (
    <div className="@container flex flex-col gap-3">
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="relative min-w-0">
          <div
            ref={scrollerRef}
            className="relative h-[260px] overflow-y-auto rounded-tau-md border border-line-1 px-3 pb-3"
            style={{ scrollSnapType: type }}
          >
            <div className="flex flex-col gap-3">
              {SECTIONS.map((label, index) => (
                <SnapCard key={label} label={label} index={index} note="scroll-snap-align: start" className="h-[200px] shrink-0">
                  <span className="h-1.5 w-2/3 rounded-full bg-press" />
                </SnapCard>
              ))}
            </div>
          </div>
          <span className="pointer-events-none absolute inset-x-0 top-px border-t border-dashed border-accent" />
        </div>
        <div className="flex min-w-0 flex-col gap-2">
          <CssView
            lines={[
              [".container {"],
              ["  overflow-y: auto;"],
              ["  scroll-snap-type: ", { text: type }, ";"],
              ["}"],
            ]}
          />
          <Readout
            rows={[
              ["scrollTop", `${state.offset}px`],
              ["最近吸附点", nearest ? `${nearest.label}（${nearest.position}px）` : "—"],
              ["偏差", type === "none" ? "未开启吸附" : gap === 0 ? "已对齐" : `${gap > 0 ? "+" : ""}${gap}px`],
            ]}
          />
          <SnapRuler state={state} />
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-3">
        <ui.RadioGroup label="scroll-snap-type" value={type} onValueChange={setType} orientation="horizontal">
          {TYPES.map(value => (
            <ui.Radio key={value} value={value} label={value} />
          ))}
        </ui.RadioGroup>
      </div>
      <p className="m-0 text-tau-meta text-ink-3">在左侧滚动后松手：mandatory 总会拉回虚线对齐，proximity 只在离吸附点较近时才吸过去。</p>
    </div>
  );
};

