    {rows.map(([label, value]) => (
      <React.Fragment key={label}>
        <dt className="text-tau-sm text-ink-3">{label}</dt>
        <dd className="m-0 min-w-0 break-all font-tau-mono text-tau-sm text-ink-1">{value}</dd>
