                index={index}
                align="center"
                note={important ? "always" : "normal"}
                variant={important ? "warn" : label === current ? "active" : "default"}
                className="h-[110px] w-[180px] shrink-0"
                style={{ scrollSnapStop: important ? "always" : "normal" }}
              />
            );
          })}
        </div>
        <span className="pointer-events-none absolute inset-y-0 left-1/2 border-l border-dashed border-accent" />
      </div>
    </div>
  );
};

const Component = () => {
  const normalRef = useRef(null);
  const alwaysRef = useRef(null);
  const tracks = [normalRef, alwaysRef];

  const fling = () =>
    tracks.forEach(ref => {
      const scroller = ref.current;
      const [first, second] = scroller.querySelectorAll("[data-snap]");
      const step = second && first ? second.offsetLeft - first.offsetLeft : 0;
      scroller.scrollBy({ left: step * 4, behavior: "smooth" });
    });
  const reset = () => tracks.forEach(ref => (ref.current.scrollLeft = 0));

  return (
    <div className="flex flex-col gap-4">
      <Track scrollerRef={normalRef} always={false} />
      <Track scrollerRef={alwaysRef} always />
      <div className="flex flex-wrap items-center gap-3">
        <ui.Button variant="primary" size="sm" icon={icons.ChevronsRight} onClick={fling}>
          一次滑过 4 张
        </ui.Button>
        <ui.Button variant="ghost" size="sm" icon={icons.RotateCcw} onClick={reset}>
          回到开头
        </ui.Button>
        <span className="text-tau-meta text-ink-3">也可以用触控板在两条轨道上快速轻扫，对比是否在 {IMPORTANT} 停下</span>
      </div>
    </div>
  );
};

